from __future__ import annotations

import os
from pathlib import Path
from typing import Optional, Union, BinaryIO

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def upload_to_s3(
    file_or_bytes: Union[str, os.PathLike, bytes, bytearray, BinaryIO],
    bucket_name: str,
    object_name: str,
    *,
    region_name: Optional[str] = None,
    content_type: Optional[str] = None,
) -> str:
    """
    Upload a local file path, byte string, or file-like object to Amazon S3.

    Requires AWS credentials via environment variables or standard boto3 config:
    AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, AWS_SESSION_TOKEN (optional).
    """
    s3_client = boto3.client("s3", region_name=region_name)

    extra_args = {}
    if content_type:
        extra_args["ContentType"] = content_type

    try:
        if isinstance(file_or_bytes, (str, os.PathLike)):
            path = Path(file_or_bytes)
            with path.open("rb") as f:
                if extra_args:
                    s3_client.upload_fileobj(f, bucket_name, object_name, ExtraArgs=extra_args)
                else:
                    s3_client.upload_fileobj(f, bucket_name, object_name)
        elif isinstance(file_or_bytes, (bytes, bytearray)):
            import io

            bio = io.BytesIO(file_or_bytes)
            if extra_args:
                s3_client.upload_fileobj(bio, bucket_name, object_name, ExtraArgs=extra_args)
            else:
                s3_client.upload_fileobj(bio, bucket_name, object_name)
        else:
            if extra_args:
                s3_client.upload_fileobj(file_or_bytes, bucket_name, object_name, ExtraArgs=extra_args)
            else:
                s3_client.upload_fileobj(file_or_bytes, bucket_name, object_name)
    except (BotoCoreError, ClientError) as e:
        raise RuntimeError(f"Failed to upload object to s3://{bucket_name}/{object_name}: {e}") from e

    return f"s3://{bucket_name}/{object_name}"
